package com.t2pellet.strawgolem.fabric.events;

import net.fabricmc.fabric.api.event.Event;
import net.fabricmc.fabric.api.event.EventFactory;
import net.minecraft.core.BlockPos;
import net.minecraft.server.level.ServerLevel;

public interface CropGrowthCallback {

    Event<CropGrowthCallback> EVENT = EventFactory.createArrayBacked(CropGrowthCallback.class,
            listeners -> (world, pos) -> {
                for (CropGrowthCallback listener : listeners) {
                    listener.grow(world, pos);
                }
            });

    void grow(ServerLevel world, BlockPos pos);
}

package com.t2pellet.strawgolem.fabric.mixin;

import com.t2pellet.strawgolem.Constants;
import com.t2pellet.strawgolem.common.util.crop.CropUtil;
import com.t2pellet.strawgolem.fabric.events.CropGrowthCallback;
import net.minecraft.core.BlockPos;
import net.minecraft.server.level.ServerLevel;
import net.minecraft.world.level.Level;
import net.minecraft.world.level.block.AttachedStemBlock;
import net.minecraft.world.level.block.Block;
import net.minecraft.world.level.block.state.BlockState;
import org.spongepowered.asm.mixin.Mixin;
import org.spongepowered.asm.mixin.injection.At;
import org.spongepowered.asm.mixin.injection.Inject;
import org.spongepowered.asm.mixin.injection.callback.CallbackInfoReturnable;

@Mixin(Level.class)
public class GrowthMixin {

    @Inject(method = "setBlock(Lnet/minecraft/core/BlockPos;Lnet/minecraft/world/level/block/state/BlockState;I)Z", at = @At("TAIL"))
    public void grow(BlockPos pos, BlockState newState, int i, CallbackInfoReturnable<Boolean> info) {
        if ((Object) this instanceof ServerLevel level) {
            BlockPos cropPos = pos;
            Block block = newState.getBlock();
            if (block instanceof AttachedStemBlock) {
                cropPos = pos.offset(newState.getValue(AttachedStemBlock.FACING).getNormal());
            }
            if (CropUtil.isGrownCrop(level, pos)) {
                Constants.LOG.debug("Crop grown in world: {}, at pos: {}", level.toString(), pos.toShortString());
                BlockPos finalCropPos = cropPos;
                level.getServer().execute(() -> CropGrowthCallback.EVENT.invoker().grow(level, finalCropPos));
            }
        }
    }
}

